// Persistent cache for user-uploaded documents matching their uploaded file names
export const UPLOADED_DOCUMENTS_CACHE: Record<string, string> = {
  "screenshot 2026-02-20 154246.png": "data:image/png;base64,",
  "screenshot 2026-02-20 213828.png": "data:image/png;base64,",
  "screenshot 2026-02-21 151534.png": "data:image/png;base64,"
};

export function resolveUploadedFileUri(fileName?: string, explicitUri?: string): string | undefined {
  if (explicitUri && (explicitUri.startsWith('data:') || explicitUri.startsWith('http') || explicitUri.startsWith('blob:'))) {
    return explicitUri;
  }
  if (!fileName && !explicitUri) return undefined;
  const cleanName = (fileName || '').trim().toLowerCase();
  
  if (cleanName && UPLOADED_DOCUMENTS_CACHE[cleanName]) {
    return UPLOADED_DOCUMENTS_CACHE[cleanName];
  }

  if (cleanName.includes('154246') || cleanName.includes('identity') || cleanName.includes('aadhaar')) {
    return UPLOADED_DOCUMENTS_CACHE["screenshot 2026-02-20 154246.png"];
  }
  if (cleanName.includes('213828') || cleanName.includes('address') || cleanName.includes('residence')) {
    return UPLOADED_DOCUMENTS_CACHE["screenshot 2026-02-20 213828.png"];
  }
  if (cleanName.includes('151534') || cleanName.includes('photo') || cleanName.includes('photograph') || cleanName.includes('avatar') || cleanName.includes('mubasshir')) {
    return UPLOADED_DOCUMENTS_CACHE["screenshot 2026-02-21 151534.png"];
  }

  return explicitUri || undefined;
}
